18	
19	import java.util.Locale;
20	import java.util.Map;
21	
22	/**
23	 * Canonicalises a free-text street address: trims and collapses whitespace, upper-cases,
24	 * and expands common abbreviations (ST -> STREET, RD -> ROAD, AVE -> AVENUE). A blank or
25	 * {@code null} input normalises to the empty string.
26	 */
27	final class AddressNormalizer {
28	
29	    private static final Map<String, String> ABBREVIATIONS =
30	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
31	
32	    private AddressNormalizer() {
33	    }
34	
35	    static String normalize(String address) {
36	        if (address == null) {
37	            return "";
38	        }
39	        String cleaned = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
40	        if (cleaned.isEmpty()) {
41	            return "";
42	        }
43	        String[] tokens = cleaned.split(" ");
44	        StringBuilder sb = new StringBuilder(cleaned.length());
45	        for (int i = 0; i < tokens.length; i++) {
46	            if (i > 0) {
47	                sb.append(' ');
48	            }
49	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
50	        }
51	        return sb.toString();
52	    }
53	}
