18	
19	import java.util.List;
20	import java.util.Locale;
21	
22	import org.springframework.validation.Errors;
23	
24	/**
25	 * Rejects an owner whose email address uses a known disposable-email domain, so throwaway
26	 * mailboxes cannot be used to register.
27	 */
28	final class DisposableEmailDomains {
29	
30	    private static final List<String> BLOCKED =
31	        List.of("mailinator.com", "tempmail.com", "guerrillamail.com");
32	
33	    private DisposableEmailDomains() {
34	    }
35	
36	    static void reject(String email, Errors errors) {
37	        if (email == null) {
38	            return;
39	        }
40	        int at = email.lastIndexOf('@');
41	        String domain = at < 0 ? "" : email.substring(at + 1).toLowerCase(Locale.ROOT);
42	        if (BLOCKED.contains(domain)) {
43	            errors.rejectValue("email", "email", "must not use a disposable-email domain");
44	        }
45	    }
46	}
