17	package org.springframework.samples.petclinic.rest.advice;
18	
19	/**
20	 * Validates an E.164 telephone number, enforcing the national-number length required by its
21	 * country code: {@code +61} needs 9 national digits and {@code +1} needs 10. Other country
22	 * codes fall back to the general 8-15 digit rule.
23	 */
24	final class E164Telephone {
25	
26	    private E164Telephone() {
27	    }
28	
29	    static boolean isValid(String e164) {
30	        String digits = e164.startsWith("+") ? e164.substring(1) : "";
31	        if (!digits.matches("\\d{8,15}")) {
32	            return false;
33	        }
34	        if (e164.startsWith("+61")) {
35	            return digits.length() == 11; // 2-digit country code + 9 national digits
36	        }
37	        if (e164.startsWith("+1")) {
38	            return digits.length() == 11; // 1-digit country code + 10 national digits
39	        }
40	        return true;
41	    }
42	}
