18	
19	import java.io.IOException;
20	import java.util.Map;
21	import java.util.concurrent.ConcurrentHashMap;
22	
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.MediaType;
25	import org.springframework.stereotype.Component;
26	import org.springframework.web.filter.OncePerRequestFilter;
27	import org.springframework.web.util.ContentCachingResponseWrapper;
28	
29	import jakarta.servlet.FilterChain;
30	import jakarta.servlet.ServletException;
31	import jakarta.servlet.http.HttpServletRequest;
32	import jakarta.servlet.http.HttpServletResponse;
33	
34	/**
35	 * Makes owner creation idempotent: when a {@code POST /api/owners} carries an
36	 * {@code Idempotency-Key} already seen, the originally created owner is replayed
37	 * with {@code 200 OK} instead of the request creating a duplicate.
38	 */
39	@Component
40	public class IdempotentOwnerCreateFilter extends OncePerRequestFilter {
41	
42	    private final Map<String, byte[]> replies = new ConcurrentHashMap<>();
43	
44	    @Override
45	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
46	                                    FilterChain chain) throws ServletException, IOException {
47	        String key = request.getHeader("Idempotency-Key");
48	        boolean create = "POST".equalsIgnoreCase(request.getMethod())
49	            && request.getRequestURI().endsWith("/api/owners");
50	        if (key == null || !create) {
51	            chain.doFilter(request, response);
52	            return;
53	        }
54	        byte[] seen = replies.get(key);
55	        if (seen != null) {
56	            response.setStatus(HttpStatus.OK.value());
57	            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
58	            response.getOutputStream().write(seen);
59	            return;
60	        }
61	        ContentCachingResponseWrapper caching = new ContentCachingResponseWrapper(response);
62	        chain.doFilter(request, caching);
63	        if (caching.getStatus() >= 200 && caching.getStatus() < 300) {
64	            replies.putIfAbsent(key, caching.getContentAsByteArray());
65	        }
66	        caching.copyBodyToResponse();
67	    }
68	}
