1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.Collection;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Households are keyed deterministically on (normalized last name, postcode): every owner carries
11	 * the household id derived from those two fields, so owners that share them belong to the same
12	 * household automatically. {@code sharesHousehold} no longer creates the link (the id is always
13	 * computed); it only lets a further member of an existing household bypass the duplicate block.
14	 */
15	final class HouseholdDuplicates {
16	
17	    private HouseholdDuplicates() {
18	    }
19	
20	    /**
21	     * Stamps {@code candidate} with its deterministic household id (first 12 hex characters of
22	     * SHA-256 over {@code normalizedLastName + '|' + postcode}).
23	     */
24	    static void assignHousehold(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
25	        candidate.setHouseholdId(householdId(candidate));
26	    }
27	
28	    /**
29	     * Returns {@code true} when an existing owner already belongs to {@code candidate}'s household
30	     * and the request did not opt in via {@code sharesHousehold}.
31	     */
32	    static boolean isRejectedDuplicate(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
33	        if (Boolean.TRUE.equals(sharesHousehold)) {
34	            return false;
35	        }
36	        String id = householdId(candidate);
37	        return existing.stream().anyMatch(other -> id.equals(householdId(other)));
38	    }
39	
40	    /** First 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. */
41	    static String householdId(Owner owner) {
42	        String key = norm(owner.getLastName()) + "|" + blank(owner.getPostcode());
43	        try {
44	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
45	            StringBuilder sb = new StringBuilder();
46	            for (int i = 0; i < 6; i++) {
47	                sb.append(String.format("%02x", digest[i]));
48	            }
49	            return sb.toString();
50	        }
51	        catch (Exception e) {
52	            throw new IllegalStateException(e);
53	        }
54	    }
55	
56	    private static String blank(String value) {
57	        return value == null ? "" : value;
58	    }
59	
60	    private static String norm(String value) {
61	        return value == null ? "" : value.replaceAll("\\s+", " ").trim().toLowerCase();
62	    }
63	}
