2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Soft duplicate detection. A candidate that is not a hard {@link IdentityKey} duplicate but shares
9	 * an existing owner's household (same computed household id) while using a different telephone is a
10	 * possible duplicate of that owner. A declared household member ({@code sharesHousehold}) is not a
11	 * suspected duplicate.
12	 */
13	final class PossibleDuplicates {
14	
15	    private PossibleDuplicates() {
16	    }
17	
18	    /** Id of the earliest existing owner {@code candidate} softly duplicates, or {@code null} when none. */
19	    static Integer matchId(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
20	        if (Boolean.TRUE.equals(sharesHousehold) || candidate.getHouseholdId() == null) {
21	            return null;
22	        }
23	        String id = candidate.getHouseholdId();
24	        return existing.stream()
25	            .filter(other -> id.equals(other.getHouseholdId()))
26	            .filter(other -> !candidate.getTelephone().equals(other.getTelephone()))
27	            .map(Owner::getId)
28	            .filter(other -> other != null)
29	            .min(Integer::compareTo)
30	            .orElse(null);
31	    }
32	}
