3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Counts owners that are namesakes, i.e. share the same firstName and lastName
9	 * (compared case-insensitively).
10	 */
11	final class Namesakes {
12	
13	    private Namesakes() {
14	    }
15	
16	    /** Number of {@code existing} owners sharing {@code candidate}'s firstName and lastName. */
17	    static int count(Owner candidate, Collection<Owner> existing) {
18	        return (int) existing.stream()
19	            .filter(other -> eq(other.getFirstName(), candidate.getFirstName())
20	                && eq(other.getLastName(), candidate.getLastName()))
21	            .count();
22	    }
23	
24	    private static boolean eq(String a, String b) {
25	        return a != null && a.equalsIgnoreCase(b);
26	    }
27	}
