12	 * Builds an owner's customerCode in the form {@code <REGION>-<HASH8>}: the region derived
13	 * from the postcode, then the first 8 upper-case hex characters of SHA-256 over the
14	 * owner's normalized telephone and last name.
15	 */
16	public final class CustomerCodes {
17	
18	    private CustomerCodes() {
19	    }
20	
21	    /** The {@code <REGION>-<HASH8>} identity code for {@code owner}. */
22	    static String build(Owner owner, Collection<Owner> existing) {
23	        return deduplicate(region(owner) + "-" + hash8(owner.getTelephone() + owner.getLastName()), existing);
24	    }
25	
26	    /** {@code code}, or the first {@code code-<n>} (n starting at 2) not held by an owner in {@code existing}. */
27	    private static String deduplicate(String code, Collection<Owner> existing) {
28	        Set<String> used = new HashSet<>();
29	        for (Owner owner : existing) {
30	            used.add(owner.getCustomerCode());
31	        }
32	        String candidate = code;
33	        for (int n = 2; used.contains(candidate); n++) {
34	            candidate = code + "-" + n;
35	        }
36	        return candidate;
37	    }
38	
39	    /** The region code derived from {@code owner}'s postcode, falling back to its city, else {@code UNKNOWN}. */
40	    public static String region(Owner owner) {
41	        String prefix = owner.getPostcode() != null && owner.getPostcode().matches("[0-9]{4}")
42	            ? owner.getPostcode().substring(0, 2) : "";
43	        return switch (prefix) {
44	            case "20" -> "NSW";
45	            case "30" -> "VIC";
46	            case "40" -> "QLD";
47	            default -> switch (owner.getCity() == null ? "" : owner.getCity()) {
48	                case "Sydney" -> "NSW";
49	                case "Melbourne" -> "VIC";
50	                case "Brisbane" -> "QLD";
51	                default -> "UNKNOWN";
52	            };
53	        };
54	    }
55	
56	    /** The first 8 upper-case hex characters of SHA-256 over {@code value}. */
57	    private static String hash8(String value) {
58	        try {
59	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
60	            StringBuilder sb = new StringBuilder();
61	            for (int i = 0; i < 4; i++) {
62	                sb.append(String.format("%02X", digest[i]));
63	            }
64	            return sb.toString();
65	        }
66	        catch (Exception e) {
67	            throw new IllegalStateException(e);
68	        }
69	    }
70	}
