9	/**
10	 * Flags a bulk signup: {@code true} once more than {@link #THRESHOLD} owners have
11	 * already been created today (compared by {@code registrationDate}).
12	 */
13	final class BulkSignupWarning {
14	
15	    static final int THRESHOLD = 80;
16	
17	    private BulkSignupWarning() {
18	    }
19	
20	    /**
21	     * Returns {@code true} when more than {@link #THRESHOLD} of the {@code existing}
22	     * owners were already registered today.
23	     */
24	    static boolean isTriggered(Collection<Owner> existing) {
25	        LocalDate today = BusinessDays.roll(LocalDate.now());
26	        long createdToday = existing.stream()
27	            .filter(other -> today.equals(other.getRegistrationDate()))
28	            .count();
29	        return createdToday > THRESHOLD;
30	    }
31	}
